<script setup lang="ts">import { onMounted, ref } from 'vue'; import { Cable, Plus, Radio, Trash2, ToggleLeft, ToggleRight } from 'lucide-vue-next'; import PageHeader from '../components/PageHeader.vue'; import EmptyState from '../components/EmptyState.vue'; import { useResourcesStore } from '../stores/resources'; import { useAppStore } from '../stores/app'; import { api } from '../api/client'; const store = useResourcesStore(); const app = useAppStore(); const show = ref(false); const name = ref(''); const conversation = ref(''); onMounted(() => store.loadSources()); async function add() { if (!conversation.value.trim()) return; try { const item = await api.createSource({ platform: 'onebot', conversation_id: conversation.value.trim(), name: name.value.trim(), enabled: true, auto_extract: true, context_window: 5, privacy_policy: 'default' }); store.sources.push(item); show.value = false; name.value = ''; conversation.value = ''; app.toast('消息源已添加') } catch (e) { app.toast(e instanceof Error ? e.message : '添加失败') } } async function toggle(source: any) { try { const saved = await api.updateSource(source.id, { enabled: !source.enabled }); Object.assign(source, saved); app.toast(saved.enabled ? '已启用消息源' : '已暂停消息源') } catch (e) { app.toast(e instanceof Error ? e.message : '更新失败') } } async function remove(id:number) { if (!confirm('确定移除这个消息源吗？')) return; try { await api.deleteSource(id); store.sources = store.sources.filter(s => s.id !== id); app.toast('消息源已移除') } catch (e) { app.toast(e instanceof Error ? e.message : '移除失败') } }</script>
<template><section class="page-content"><PageHeader eyebrow="数据入口" title="连接" description="管理 CampusCue 读取校园消息的入口。"><button class="button button-primary" @click="show = !show"><Plus :size="16" />添加连接</button></PageHeader><form v-if="show" class="form-card panel" @submit.prevent="add"><div class="form-grid"><label>显示名称<input v-model="name" placeholder="例如：高数课程群" /></label><label>会话标识<input v-model="conversation" required placeholder="会话 ID" /></label></div><p class="form-help">只保存连接配置，不会在前端展示或保存消息源密钥。</p><div class="form-actions"><button type="button" class="button button-secondary" @click="show = false">取消</button><button class="button button-primary">保存连接</button></div></form><section class="connection-grid" v-if="store.sources.length"><article v-for="source in store.sources" :key="source.id" class="panel connection-card"><div class="connection-card-top"><div class="source-icon"><Radio :size="19" /></div><div><h3>{{ source.name || source.conversation_id }}</h3><p>{{ source.platform }} · {{ source.conversation_id }}</p></div><span class="status-badge" :class="source.enabled ? 'success' : 'muted'">{{ source.enabled ? '已启用' : '已暂停' }}</span></div><div class="connection-meta"><span>自动提取任务 <strong>{{ source.auto_extract ? '开启' : '关闭' }}</strong></span><span>上下文窗口 <strong>{{ source.context_window }} 条</strong></span></div><div class="card-actions"><button class="button button-secondary" @click="toggle(source)"><component :is="source.enabled ? ToggleRight : ToggleLeft" :size="16" />{{ source.enabled ? '暂停' : '启用' }}</button><button class="icon-button danger-button" :aria-label="`移除${source.name || source.conversation_id}`" @click="remove(source.id)"><Trash2 :size="17" /></button></div></article></section><section v-else class="panel"><EmptyState title="还没有连接" description="添加一个消息源后，CampusCue 才能从校园消息中提取事务。" /></section></section></template>
